// Formal defect report, generated by the system when a resident submits a report.
// Layout follows a landscape architect's defect list: a cover page with sign-off
// boxes, then a table of ITEM / PHOTO OF DEFECT / DEFECT AS COMMENTED / RECTIFICATION.

const CAT = { obstruction: 'Obstruction', surface: 'Surface damage', steps: 'Steps' };
const SEVERITY = { blocked: 'Blocks the journey', difficult: 'Makes it difficult', minor: 'Minor inconvenience' };
const STATUS = {
  new: 'New — awaiting verification',
  verified: 'Verified — awaiting assignment',
  assigned: 'Work assigned',
  awaiting_confirmation: 'Completion submitted — awaiting confirmation',
  confirmed: 'Resolved',
  closed: 'Closed',
};
const LOGO = `<svg width="54" height="54" viewBox="0 0 100 100" aria-hidden="true">
  <rect width="100" height="100" rx="24" fill="#D62828"/>
  <circle cx="45" cy="45" r="24" fill="none" stroke="#FFF3E0" stroke-width="7"/>
  <line x1="62.5" y1="62.5" x2="77" y2="77" stroke="#FFF3E0" stroke-width="8" stroke-linecap="round"/>
  <path d="M31 53 H39 L51 41 H59" fill="none" stroke="#FFF3E0" stroke-width="4.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;

const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

function ordinalDate(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  const n = d.getDate();
  const suf = n % 10 === 1 && n !== 11 ? 'st' : n % 10 === 2 && n !== 12 ? 'nd' : n % 10 === 3 && n !== 13 ? 'rd' : 'th';
  return `${n}<sup>${suf}</sup> ${d.toLocaleDateString('en-GB', { month: 'long', year: 'numeric' })}`;
}
const plainDate = (iso) => (iso ? new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' }) : '');
const dateTime = (iso) =>
  iso ? new Date(iso).toLocaleString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', hour: 'numeric', minute: '2-digit' }) : '';

function photo(src, ai, alt) {
  const b = ai && !ai.noBarrier && ai.box;
  return `<figure class="shot"><img src="${esc(src)}" alt="${esc(alt)}"/>${
    b ? `<span class="mark" style="left:${b.x * 100}%;top:${b.y * 100}%;width:${b.w * 100}%;height:${b.h * 100}%"></span>` : ''
  }</figure>`;
}

function sign(role, org, sub, sig, name, designation, date) {
  return `<div class="sign">
    <div>${esc(role)}</div>
    <div class="org">${esc(org)}</div>
    <div class="sub">${esc(sub)}</div>
    <div class="sigbox">${sig ? `<img src="${esc(sig)}" alt="Signature of ${esc(name || role)}"/>` : ''}</div>
    <div class="line"></div>
    <div>Name: <span class="fill">${name ? esc(name) : '……………………'}</span></div>
    <div>Designation: <span class="fill">${designation ? esc(designation) : '…………………'}</span></div>
    ${sig && date ? `<div class="signed">Signed ${esc(plainDate(date))}</div>` : ''}
  </div>`;
}

function render(r) {
  const fr = r.formalReport;
  const reportedOn = ordinalDate(r.createdAt);
  const place = r.address || 'Pinned location';
  const project = `ACCESSIBILITY DEFECT REPORT FOR THE PEDESTRIAN WALKWAY AT ${place.toUpperCase()}`;
  const staffCat = r.staffCategory && r.staffCategory !== fr.category ? `<p class="note">Category verified by staff as <b>${esc(CAT[r.staffCategory])}</b>.</p>` : '';
  const done = r.completionPhoto;
  const sg = r.signatures || {};
  const pr = r.priority || { level: (fr.priority || 'medium').toLowerCase(), label: fr.priority || 'Medium', score: '–', reasons: [] };
  document.title = `${fr.number} · ${r.code} defect report`;

  document.getElementById('doc').innerHTML = `
  <section class="page cover">
    <div class="ref">${esc(fr.number)} · ${esc(r.code)}</div>
    <h1 class="project">${esc(project)}</h1>
    <h2 class="title">DEFECT LIST</h2>
    <div class="band">RESIDENT REPORT ON ${reportedOn}</div>
    <div class="brand">${LOGO}<div><b>AccessLens</b><small>AI-assisted accessibility reporting</small></div></div>
    <div class="signs">
      ${sign('Acknowledged by:', 'TOWNSHIP MANAGEMENT', '(Client)', sg.verify, r.verifiedBy, r.verifiedBy ? 'Verifying staff' : null, r.verifiedAt)}
      ${sign('Agreed by:', (r.team || 'MAINTENANCE TEAM').toUpperCase(), '(Maintenance contractor)', sg.completion, sg.completedBy, sg.completedBy ? `Maintenance · ${r.team || ''}` : null, r.completedAt)}
      ${sign('Confirmed by:', 'RESIDENT', '(Report sender)', sg.resident, r.feedback?.fixed ? sg.residentName || r.resident?.name || 'Resident' : null, r.feedback?.fixed ? 'Report sender' : null, r.feedback?.at)}
    </div>
    <p class="gen">Prepared automatically by the AccessLens system on ${esc(dateTime(fr.generatedAt))} when the resident submitted the report. Status today: <b>${esc(STATUS[r.status] || r.status)}</b>.</p>
  </section>

  <section class="page">
    <header class="runhead">
      <div class="proj">${esc(project)}</div>
      <div class="row"><span class="section">${esc(fr.section)}</span><span>RESIDENT REPORT ON ${reportedOn}</span><span>${esc(fr.number)}</span></div>
    </header>
    <table class="defects">
      <colgroup><col style="width:6%"/><col style="width:42%"/><col style="width:26%"/><col style="width:26%"/></colgroup>
      <thead><tr><th>ITEM</th><th>PHOTO OF DEFECT</th><th>DEFECT AS COMMENTED BY SYSTEM</th><th>RECTIFICATION WORKS BY CONTRACTOR</th></tr></thead>
      <tbody><tr>
        <td class="item">1</td>
        <td>${photo(r.photo, r.ai, 'Resident photo of the defect')}
          <div class="cap">Resident photo · ${esc(r.code)}${r.ai && !r.ai.noBarrier && r.ai.box ? ' · AI highlight in red' : ''}</div></td>
        <td class="comments">
          ${fr.comments.map((c) => `<p>${esc(c)}</p>`).join('')}
          ${fr.residentWords ? `<p class="quote">Resident: “${esc(fr.residentWords)}”</p>` : ''}
          ${staffCat}
          <p class="prio">Priority: <b class="p-${esc(pr.level)}">${esc(pr.label)}</b> <span class="pts">(${pr.score} pts${pr.overridden ? ', set by staff' : ''})</span></p>
          <p class="why">${pr.reasons.map((x) => `${esc(x.text)} +${x.points}`).join(' · ')}</p>
        </td>
        <td class="rect">${
          done
            ? `${photo(r.completionPhoto, null, 'Photo after the works')}
               <div class="cap">After works · ${esc(plainDate(r.completedAt))}</div>
               ${r.completionNote ? `<p>${esc(r.completionNote)}</p>` : ''}
               ${r.resolvedAt ? `<p class="ok">Confirmed by ${esc(r.resolvedBy || 'staff')} on ${esc(plainDate(r.resolvedAt))}.</p>` : '<p class="note">Awaiting confirmation by township staff.</p>'}
               ${r.feedback ? `<p class="note">Resident feedback: ${r.feedback.fixed ? 'walkway is usable now' : 'not fixed yet'}.</p>` : ''}`
            : r.status === 'closed'
              ? `<p class="note">Report closed: ${esc(r.closedReason || '')}</p>`
              : `<div class="blank"><span></span><span></span><span></span><span></span></div>
                 ${r.workNote ? `<p class="note">Instruction: ${esc(r.workNote)}</p>` : ''}`
        }</td>
      </tr></tbody>
    </table>
  </section>

  <section class="page">
    <header class="runhead">
      <div class="proj">${esc(project)}</div>
      <div class="row"><span class="section">Report details</span><span>RESIDENT REPORT ON ${reportedOn}</span><span>${esc(fr.number)}</span></div>
    </header>
    <table class="details">
      <tr><th>Report reference</th><td>${esc(r.code)} · ${esc(fr.number)}</td><th>Status</th><td>${esc(STATUS[r.status] || r.status)}</td></tr>
      <tr><th>Reported</th><td>${esc(dateTime(r.createdAt))}</td><th>Priority</th><td>${esc(pr.label)} · ${pr.score} pts${pr.overridden ? ' (set by staff)' : ''}</td></tr>
      <tr><th>Location</th><td>${esc(place)}${r.landmark ? ` · ${esc(r.landmark)}` : ''}</td><th>Coordinates</th><td>${r.lat != null ? `${r.lat.toFixed(5)}, ${r.lng.toFixed(5)}` : '—'}</td></tr>
      <tr><th>Barrier type</th><td>${esc(CAT[r.category])}${r.staffCategory ? ' (verified)' : ' (resident)'}</td><th>Effect on journey</th><td>${esc(SEVERITY[r.severity] || '—')}</td></tr>
      <tr><th>AI assessment</th><td>${r.ai ? (r.ai.noBarrier ? 'No barrier spotted' : `${esc(CAT[r.ai.category])} · ${Math.round(r.ai.confidence * 100)}%`) : 'Not available'}</td><th>Responsible team</th><td>${esc(r.team || 'To be assigned')}</td></tr>
      <tr><th>Work type</th><td>${esc(r.workType ? (r.workType === 'inspection' ? 'Inspection' : 'Repair') : '—')}</td><th>Target date</th><td>${esc(plainDate(r.dueDate) || '—')}</td></tr>
    </table>
    <h3>Record</h3>
    <table class="log">
      <thead><tr><th>Date</th><th>Event</th><th>By</th></tr></thead>
      <tbody>${(r.events || [])
        .filter((e) => e.public || e.kind === 'formal_report')
        .map((e) => `<tr><td>${esc(dateTime(e.at))}</td><td>${esc(e.note)}</td><td>${esc(e.by || { resident: 'Resident', ai: 'System', staff: 'Staff', admin: 'Admin' }[e.actor] || '')}</td></tr>`)
        .join('')}</tbody>
    </table>
    <p class="foot">This defect report was generated by AccessLens from the resident's report. AI suggestions are verified by township staff on site before any action.</p>
  </section>`;
}

async function load() {
  const id = new URLSearchParams(location.search).get('id');
  document.getElementById('back').href = `./#/report/${id}`;
  document.getElementById('print').addEventListener('click', () => window.print());
  const token = localStorage.getItem('al_token');
  const doc = document.getElementById('doc');
  if (!token) {
    doc.innerHTML = '<p class="loading">Please log in to the staff website first, then open the report again.</p>';
    return;
  }
  try {
    const res = await fetch(`/api/staff/reports/${encodeURIComponent(id)}`, { headers: { Authorization: `Bearer ${token}` } });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || `Error ${res.status}`);
    render(data.report);
  } catch (e) {
    doc.innerHTML = `<p class="loading">Couldn’t load this report: ${esc(e.message)}</p>`;
  }
}
load();
